/* ceil with the evaluator's 1e-9 snap to the nearest whole number */
static double aven_ceil(double v) {
    const double r = round(v);
    const double snap = (double)(fabs(v - r) < 1e-9);
    return snap * r + (1.0 - snap) * ceil(v);
}

/* eBPF uprobe export: preserve symbol in .symtab under -O2 and prevent IPA cloning */
